import{_ as r,C as c,o as e,c as s,a3 as d,b as n,w as o,a as i,E as l,a4 as p}from"./chunks/framework.DU3q3XnC.js";const R=JSON.parse('{"title":"Cocos粒子杂项暂存","description":"","frontmatter":{},"headers":[],"relativePath":"图形学/cocos粒子杂项暂存.md","filePath":"图形学/cocos粒子杂项暂存.md","lastUpdated":null}'),h={name:"图形学/cocos粒子杂项暂存.md"};function u(g,t,E,b,A,m){const a=c("Mermaid");return e(),s("div",null,[t[1]||(t[1]=d(`<h1 id="cocos粒子杂项暂存" tabindex="-1">Cocos粒子杂项暂存 <a class="header-anchor" href="#cocos粒子杂项暂存" aria-label="Permalink to &quot;Cocos粒子杂项暂存&quot;">​</a></h1><h2 id="_2d粒子类型分类" tabindex="-1">2D粒子类型分类 <a class="header-anchor" href="#_2d粒子类型分类" aria-label="Permalink to &quot;2D粒子类型分类&quot;">​</a></h2><p>cocos2d 粒子主要可以按两个正交的维度分类：运动状态 x 位置</p><h3 id="运动状态" tabindex="-1">运动状态 <a class="header-anchor" href="#运动状态" aria-label="Permalink to &quot;运动状态&quot;">​</a></h3><p>按照运动状态可以分为 GRAVITY 和 RADIUS</p><h4 id="gravity-笛卡尔速度-牛顿积分" tabindex="-1">GRAVITY：笛卡尔速度 + 牛顿积分 <a class="header-anchor" href="#gravity-笛卡尔速度-牛顿积分" aria-label="Permalink to &quot;GRAVITY：笛卡尔速度 + 牛顿积分&quot;">​</a></h4><p>速度存在 <code>dir</code> 里。每帧先累加速度，再积分位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>radialDir     = normalize(pos)                 // 相对发射源；在原点则为 0</span></span>
<span class="line"><span>tangentialDir = (-radialDir.y, radialDir.x)    // 逆时针 90°</span></span>
<span class="line"><span>vel += (gravity + radialDir * radialAccel + tangentialDir * tangentialAccel) * dt</span></span>
<span class="line"><span>pos += vel * dt * yCoordFlipped</span></span></code></pre></div><h5 id="三个加速度-两套坐标系" tabindex="-1">三个加速度：两套坐标系 <a class="header-anchor" href="#三个加速度-两套坐标系" aria-label="Permalink to &quot;三个加速度：两套坐标系&quot;">​</a></h5><ul><li><code>gravity</code>：世界轴上的常向量，<strong>所有粒子同一方向</strong>（通常往下）。不依赖粒子在哪，一个数就够。</li><li><code>radialAccel</code> / <code>tangentialAccel</code>：围着<strong>发射源</strong>的极坐标分解。方向依赖粒子位置，不能写成固定向量。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        tangential (-ry, rx) 逆时针</span></span>
<span class="line"><span>              ↑</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>    发射源 ·--+--&gt; radial (rx, ry) 沿「源→粒子」</span></span>
<span class="line"><span>              |</span></span>
<span class="line"><span>              某粒子</span></span></code></pre></div><h5 id="为什么是两个参数" tabindex="-1">为什么是两个参数 <a class="header-anchor" href="#为什么是两个参数" aria-label="Permalink to &quot;为什么是两个参数&quot;">​</a></h5><p>相对发射源，任意力都能拆成「沿半径」和「垂直半径」两个分量——这是 2D 力场的两个自由度，也是给美术的两个旋钮：</p><ul><li>径向：改<strong>离发射源的远近</strong>。正的往外推（爆炸），负的往里拉（Galaxy 收束）。</li><li>切向：改<strong>绕发射源的角度</strong>，不直接改距离。有它才会转（Spiral）。</li></ul><p>只留 <code>gravity</code>，所有粒子永远被推向同一方向，做不出「绕着喷口转」或「被吸回中心」；只留径向，只能胀缩，转不起来。三者叠起来，才覆盖烟 / 烟花 / 星系 / 螺旋。</p><p>两个标量对所有粒子共用，方向却每帧随粒子当前位置重算——飞到哪里，力就指向「源→粒子」或垂直于它。出生时写死一个 <code>(ax, ay)</code> 做不到：飞走之后那个向量还指着旧方向，中心吸、螺旋都会散掉。</p><h5 id="实例与对比" tabindex="-1">实例与对比 <a class="header-anchor" href="#实例与对比" aria-label="Permalink to &quot;实例与对比&quot;">​</a></h5><p>引擎里的现成例子就是按这两个旋钮配的：<code>ParticleGalaxy</code> 径向 <code>-80</code> + 切向 <code>80</code>（往里收同时转）；<code>ParticleFlower</code> <code>-60</code> / <code>15</code>；<code>ParticleSpiral</code> <code>-380</code> / <code>45</code>（强吸、慢转，收成螺旋）。Fire / Smoke / Fireworks 两个都是 0，只靠出生 <code>speed</code> 和 <code>gravity</code>。</p><p>和 RADIUS 模式的差别：这里粒子仍有速度、有惯性，力只是在推它；RADIUS 每帧用 <code>(r, θ)</code> 重写位置，没有「飞过去被吸弯」这种惯性。GRAVITY 模式用两个标量换来的，是中心力场 + 牛顿积分可以叠在一起（星系还能再往下掉）。</p><h4 id="radius-极坐标-直接重算位置" tabindex="-1">RADIUS：极坐标 + 直接重算位置 <a class="header-anchor" href="#radius-极坐标-直接重算位置" aria-label="Permalink to &quot;RADIUS：极坐标 + 直接重算位置&quot;">​</a></h4><p>每颗粒子带着：</p><ul><li><code>angle</code>：弧度</li><li><code>degreesPerSecond</code>：角速度（名字是度，<strong>存的是弧度/秒</strong>）</li><li><code>radius</code> / <code>deltaRadius</code>：当前半径、每秒半径变化</li></ul><p>每帧不积速度，直接重算位置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>angle  += ω * dt</span></span>
<span class="line"><span>radius += deltaRadius * dt</span></span>
<span class="line"><span>pos = (-cos(angle) * radius, -sin(angle) * radius * yCoordFlipped)</span></span></code></pre></div><p>负号是 Particle Designer 约定。轨迹只能是「绕发射源的圆/螺线」：半径不变就是转圈，半径收到 0 就是往里卷。没有重力、没有切向这两个独立力。</p><p>两种状态<strong>不能混在一颗粒子上</strong>。SoA 里 <code>modeA</code> 和 <code>modeB</code> 数组都分配了，但 <code>update</code> 只进一个分支。要烟花往下掉用 GRAVITY；要法阵绕点转用 RADIUS。</p><h3 id="位置-已出生粒子钉在哪" tabindex="-1">位置：已出生粒子钉在哪 <a class="header-anchor" href="#位置-已出生粒子钉在哪" aria-label="Permalink to &quot;位置：已出生粒子钉在哪&quot;">​</a></h3><p>模拟始终在发射源局部。位置类型回答的是另一件事：喷出来之后，发射器（或别人）跑了，<strong>已经活着的粒子跟不跟</strong>。</p><p>粒子自己该飞还是飞，只是「家」订在哪不同：FREE 订在世界上出生的那个点，后面三种订在某个节点上。</p><p>出生时记下 <code>startPos</code>（参考点），画的时候再取一次「当前参考点」，用两者的差去折 <code>pos</code>。GROUPED 记下了也不用。</p><table tabindex="0"><thead><tr><th>类型</th><th>出生 startPos</th><th>发射器平移</th><th>发射器旋转/缩放</th><th>典型用法</th></tr></thead><tbody><tr><td>FREE</td><td>当时的世界坐标</td><td>不管</td><td>不跟（补偿掉了）</td><td>拖尾、爆炸碎屑留在原地</td></tr><tr><td>RELATIVE</td><td>节点 <code>_position</code></td><td>跟着</td><td>不跟旋转</td><td>挂在精灵上，要平移不要拧</td></tr><tr><td>TRACK</td><td>Track 节点局部</td><td>跟 Track</td><td>不跟旋转</td><td>系统挂在 A，却跟着父节点 B</td></tr><tr><td>GROUPED</td><td>写了不用</td><td>跟着</td><td><strong>完整跟着</strong></td><td>绑在角色/武器上一起转</td></tr></tbody></table><h4 id="free-不跟" tabindex="-1">FREE：不跟 <a class="header-anchor" href="#free-不跟" aria-label="Permalink to &quot;FREE：不跟&quot;">​</a></h4><p>烟已经喷到路上了，人走开，烟还留在原地继续飘。适合拖尾、爆炸碎屑。</p><p>发射器从世界点 W0 走到 W1。某粒子出生时 <code>startPos = W0</code>，局部 <code>pos</code> 是相对发射源的位移。画的时候把 W1 和 W0 都变到节点空间，差就是发射器这段时间的位移，从 <code>pos</code> 里减掉，粒子留在出生时的世界点附近（再加上它自己飞过的 <code>pos</code> 变化）。所以烟的尾巴留在走过的路上。</p><p>加速度<strong>不看</strong> FREE。径向 / 切向每帧仍是 <code>normalize(局部 pos)</code>，力心永远是模拟原点 <code>(0,0)</code>，也就是发射器当前的局部原点。FREE 只改画：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>画面世界位置 ≈ 出生时发射器世界点 W0 + 局部 pos</span></span></code></pre></div><p>局部 pos 被吸向 0，画面上就是被吸向 <strong>W0</strong>（这颗粒子出生时喷口在哪），不是现在的 W1。各颗的 <code>startPos</code> 不同，看起来就像每颗自带一口「出生时钉住的井」。<code>gravity</code> 同样在局部轴上加，FREE 也不改它的算法。Fire / Smoke 径向切向常为 0，发射器走开只剩初速和重力，这个错位看不出来。GROUPED 没有这层折算，吸向 0 就是吸向现在的喷口。</p><h4 id="relative-跟平移-不跟旋转" tabindex="-1">RELATIVE：跟平移，不跟旋转 <a class="header-anchor" href="#relative-跟平移-不跟旋转" aria-label="Permalink to &quot;RELATIVE：跟平移，不跟旋转&quot;">​</a></h4><p>喷口绑在角色身上，角色跑，烟团一起跑；角色转身，烟的形状不跟着拧。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>newPos = pos - (currentRef - startPos)</span></span></code></pre></div><p><code>currentRef - startPos</code> 是参考点这一帧相对出生时的平移。减掉它，等于让局部 <code>pos</code> 跟着参考点平移。旋转、缩放不在这个减法里，所以发射器转了，粒子云的形状不跟着拧，只是整体挪地方。</p><p>头文件注释把 RELATIVE 说成 “attached to the world but follow emitter repositioning”，GROUPED 说成 “attached to the emitter”。差别是：RELATIVE 只补偿平移；GROUPED 把 <code>pos</code> 当节点局部坐标，Node 的 model-view 整套吃进去。</p><h4 id="track-跟平移-但参考另一个节点" tabindex="-1">TRACK：跟平移，但参考另一个节点 <a class="header-anchor" href="#track-跟平移-但参考另一个节点" aria-label="Permalink to &quot;TRACK：跟平移，但参考另一个节点&quot;">​</a></h4><p>和 RELATIVE 一样只跟平移，但跟的不是发射器自己，是你指定的另一个节点。</p><p><code>currentRef</code> 换成 Track 节点：粒子系统可以是角色的子节点（吃层级），运动跟随却绑在另一个节点上。<code>_trackNode == null</code> 时 TRACK 退化成 RELATIVE。</p><h4 id="grouped-平移、旋转、缩放全跟" tabindex="-1">GROUPED：平移、旋转、缩放全跟 <a class="header-anchor" href="#grouped-平移、旋转、缩放全跟" aria-label="Permalink to &quot;GROUPED：平移、旋转、缩放全跟&quot;">​</a></h4><p>死死粘在身上。跑也跟、转也跟、缩放也跟。Studio 里默认基本是这种。</p><p><code>newPos = pos</code>，不做补偿。<code>draw</code> 时 Renderer 再乘节点 MV，平移旋转缩放全部作用在每个顶点上。角色转身 90°，整团粒子一起转。这就是「附着在发射器上」。</p><h4 id="补充" tabindex="-1">补充 <a class="header-anchor" href="#补充" aria-label="Permalink to &quot;补充&quot;">​</a></h4><p>同一套 GRAVITY 烟，FREE 是走过留下一串，GROUPED 是烟团粘在角色脚上。同一套 RADIUS 转圈，FREE 是圈子钉在出生点的世界位置，GROUPED 是圈子跟着节点走、跟着转。</p><p>Studio 不读 plist 的 positionType。节点名含 <code>_free</code> 才是 FREE，否则 <strong>GROUPED</strong>。游戏里大多数 CSB 粒子其实是 GROUPED，不是引擎默认的 FREE。</p><p>位置类型<strong>不改变</strong> <code>pos</code> 的积分，所以切 PositionType 不必重算运动；但必须在出生时就定好，因为 <code>startPos</code> 的空间（世界 / 节点 / Track）已经写进粒子里。中途改类型，旧粒子的 <code>startPos</code> 和新折法会对不上。</p><h3 id="转换到-unity-两种模式各自拆成模块" tabindex="-1">转换到 Unity：两种模式各自拆成模块 <a class="header-anchor" href="#转换到-unity-两种模式各自拆成模块" aria-label="Permalink to &quot;转换到 Unity：两种模式各自拆成模块&quot;">​</a></h3><p>Unity 没有 GRAVITY / RADIUS 的类型分叉，只有一组可组合模块，于是两种模式各拆各的。</p><p><strong>GRAVITY → Force + 两条速度曲线</strong></p><table tabindex="0"><thead><tr><th>Cocos</th><th>Unity</th><th>换算</th></tr></thead><tbody><tr><td><code>gravity</code></td><td><code>Force over Lifetime</code></td><td><code>gravity / 100</code>（像素→单位），仍是加速度</td></tr><tr><td><code>radialAccel</code></td><td><code>Velocity over Lifetime → Radial</code></td><td>曲线 <code>0 → radialAccel / 100 × 名义寿命</code></td></tr><tr><td><code>tangentialAccel</code></td><td><code>Velocity over Lifetime → Orbital Z</code></td><td>曲线 <code>0 → tangentialAccel / 100 × 名义寿命</code></td></tr></tbody></table><p><code>gravity</code> 是<strong>纯单位换算</strong>：它是世界轴上的常向量，两边都是 <code>v += a*dt</code>，可逐帧数值还原。</p><p>径向 / 切向不够：cocos 每帧重算方向，累积的是<strong>向量</strong>；Unity 拿到的是随年龄线性插值的<strong>标量速度</strong>，只沿「当前」方向施加。方向固定时等价，方向一转就分叉：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cocos 累积:  (10,0) + (0,10) = (10,10)    保留旧方向的分量</span></span>
<span class="line"><span>曲线近似:    |v|=20 沿当前径向 → (0,20)   旧分量丢了</span></span></code></pre></div><p>切向还多一层错位：<code>a × t</code> 算出的是<strong>线速度</strong>，却被填进<strong>角速度</strong>槽位，缺一次 <code>ω = v / r</code>，半径越小偏得越多。</p><p><strong>RADIUS → Shape + 常量 Orbital Z / Radial</strong></p><table tabindex="0"><thead><tr><th>Cocos</th><th>Unity</th><th>换算</th></tr></thead><tbody><tr><td><code>maxRadius</code></td><td><code>Shape = Circle</code> 半径</td><td><code>maxRadius / 100</code>，出生在圆周上</td></tr><tr><td><code>degreesPerSecond</code></td><td><code>Orbital Z</code></td><td><code>× π / 180</code>，<strong>直接是角速度</strong></td></tr><tr><td><code>deltaRadius</code></td><td><code>Radial</code></td><td><code>(结束半径 - 起始半径) / 100 / 名义寿命</code></td></tr></tbody></table><p>比 GRAVITY 干净：角速度不用除 100、也不用按半径折算，写进去的是<strong>常量或随机区间</strong>，不是增长曲线——源数据本来就是角速度。</p><p>半径变化用「圆环出生 + 匀速径向收」表达，固定参数下与 cocos 的匀速绕转收束基本一致。两处缺口：出生半径与 Radial 随机<strong>没有绑定</strong>，寿命随机时不保证死时到达目标半径；出生角度固定整圆，丢了 <code>angle / angleVariance</code> 的范围。</p><p><strong>一句话</strong>：<code>gravity</code> 与 RADIUS 的角速度是<strong>换算</strong>，可等价；<code>radialAccel</code> / <code>tangentialAccel</code> 是<strong>模块参数近似</strong>，只在方向固定、寿命一致时等价。</p><h2 id="_3d粒子" tabindex="-1">3D粒子 <a class="header-anchor" href="#_3d粒子" aria-label="Permalink to &quot;3D粒子&quot;">​</a></h2><p>cocos 3d粒子整体结构不算复杂。粒子没有做类型的区分，在运行时只有一个particle类，承载了粒子的所有基础属性。 粒子从出生到渲染的流程，可以粗略分成三个阶段，三个阶段各有几种不同类型，正交组合成所有的粒子效果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>出生形状 (5 种)  →  模拟后端 (2 种)  →  渲染外观 (5 种)</span></span>
<span class="line"><span>   定初值            每帧积分            挤几何</span></span></code></pre></div><p>这里现不论模拟的后端（主要就是cpu和gpu的差异，这里暂且现略过）</p><h3 id="资产属性总览" tabindex="-1">资产属性总览 <a class="header-anchor" href="#资产属性总览" aria-label="Permalink to &quot;资产属性总览&quot;">​</a></h3><p>粒子系统的主要可编辑内容可以 <img src="https://raw.githubusercontent.com/xumyuan/image/master/20260912183227.png" alt="20260912183227"></p><h3 id="总体控制层级" tabindex="-1">总体控制层级 <a class="header-anchor" href="#总体控制层级" aria-label="Permalink to &quot;总体控制层级&quot;">​</a></h3>`,72)),(e(),n(p,null,{default:o(()=>[l(a,{id:"mermaid-416",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E2%91%A0%20useGPU%3Cbr%2F%3E%E5%94%AF%E4%B8%80%E7%9C%9F%E6%AD%A3%E7%9A%84%E7%B1%BB%E5%9E%8B%E5%88%86%E5%8F%89%EF%BC%8C%E5%86%B3%E5%AE%9A%E4%B8%8B%E9%9D%A2%E5%93%AA%E4%BA%9B%E5%B1%82%E5%AD%98%E5%9C%A8%22%5D%20--%3E%20B%0A%20%20B%5B%22%E2%91%A1%20%E5%8F%91%E5%B0%84%E8%B0%83%E5%BA%A6%3Cbr%2F%3ErateOverTime%20%2F%20rateOverDistance%20%2F%20bursts%20%2F%20duration%20%2F%20loop%22%5D%20--%3E%20C%0A%20%20C%5B%22%E2%91%A2%20%E5%87%BA%E7%94%9F%E5%88%9D%E5%A7%8B%E5%8C%96%3Cbr%2F%3EShape.emit%20%2B%20start*%20%E2%80%94%E2%80%94%20%E5%85%A8%E9%83%A8%E5%86%99%E6%AD%BB%E5%9C%A8%20_emit%20%E9%87%8C%22%5D%20--%3E%20D%0A%20%20D%5B%22%E2%91%A3%20%E6%AF%8F%E5%B8%A7%E6%BC%94%E5%8C%96%3Cbr%2F%3E%E9%87%8D%E5%8A%9B%EF%BC%88%E9%9D%9E%E6%A8%A1%E5%9D%97%EF%BC%89%20%2B%208%20%E4%B8%AA%E6%A8%A1%E5%9D%97%E6%8C%89%E5%9B%BA%E5%AE%9A%E9%A1%BA%E5%BA%8F%22%5D%20--%3E%20E%0A%20%20E%5B%22%E2%91%A4%20%E6%8F%90%E4%BA%A4%3Cbr%2F%3ErenderMode%20%E5%86%B3%E5%AE%9A%E5%87%A0%E4%BD%95%EF%BC%8Ctechnique%20%E5%86%B3%E5%AE%9A%E6%B7%B7%E5%90%88%22%5D%0A"})]),fallback:o(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=d('<blockquote><p>module只控制其中的第四层，是这个过程中唯一可插拔的层级</p></blockquote><h3 id="出生形状" tabindex="-1">出生形状 <a class="header-anchor" href="#出生形状" aria-label="Permalink to &quot;出生形状&quot;">​</a></h3><p><code>shapeModule.shapeType</code>。只决定<strong>出生时的 position 和初始方向</strong>，不决定以后怎么飞。关掉 Shape 时，所有粒子从原点沿 <code>(0,0,-1)</code> 喷出。</p><table tabindex="0"><thead><tr><th>形状</th><th>出生点</th><th>默认方向</th></tr></thead><tbody><tr><td><code>Box</code></td><td>立方体内部 / 表面 / 棱</td><td><code>(0,0,-1)</code></td></tr><tr><td><code>Circle</code></td><td>圆环带上</td><td>从圆心指向出生点</td></tr><tr><td><code>Cone</code></td><td>锥底或锥体内部</td><td>沿锥面张开</td></tr><tr><td><code>Sphere</code></td><td>球壳或球内</td><td>从球心向外</td></tr><tr><td><code>Hemisphere</code></td><td>下半球</td><td>从球心向外</td></tr></tbody></table><p>Box 的 <code>emitFrom = Edge</code> 是「从棱上喷」，不是第六种形状。没有 Rectangle。</p><h3 id="渲染外观" tabindex="-1">渲染外观 <a class="header-anchor" href="#渲染外观" aria-label="Permalink to &quot;渲染外观&quot;">​</a></h3><p><code>renderer.renderMode</code>。模拟可以相同，<strong>挤出四边形的方式不同</strong>。真正朝向在 shader <code>computeVertPos</code> 里做。</p><table tabindex="0"><thead><tr><th>枚举</th><th>值</th><th>看起来像什么</th><th>典型用途</th></tr></thead><tbody><tr><td><code>Billboard</code></td><td>0</td><td>每颗都正对相机</td><td>烟、火、光点</td></tr><tr><td><code>StrecthedBillboard</code></td><td>1</td><td>正对相机，并沿速度拉长</td><td>雨、火花、流星</td></tr><tr><td><code>HorizontalBillboard</code></td><td>2</td><td>贴在 XZ 平面</td><td>地面光圈、水波</td></tr><tr><td><code>VerticalBillboard</code></td><td>3</td><td>贴着 Y 轴，X 朝向相机</td><td>草、站立的片</td></tr><tr><td><code>Mesh</code></td><td>4</td><td>用你指定的网格</td><td>碎石、碎片</td></tr></tbody></table><p>另外还有一个<strong>可选附属外观</strong>：<code>TrailModule</code>。每个粒子走过的路径挤成一条带，只在 CPU 上有。它不是第六种 RenderMode，是第二条 Model。</p><h4 id="module" tabindex="-1">module <a class="header-anchor" href="#module" aria-label="Permalink to &quot;module&quot;">​</a></h4><p>按执行顺序排列（Shape / Trail 不在这个序列里）：</p><table tabindex="0"><thead><tr><th>#</th><th>模块</th><th>阶段</th><th>改哪个量</th><th>干什么</th><th>典型用途</th></tr></thead><tbody><tr><td>1</td><td><code>SizeOvertimeModule</code></td><td>每帧</td><td><code>size</code></td><td>尺寸随寿命变化</td><td>烟变大、火花变小</td></tr><tr><td>2</td><td><code>ColorOvertimeModule</code></td><td>每帧</td><td><code>color</code></td><td>颜色与透明度随寿命变化</td><td>火焰黄→红、渐隐</td></tr><tr><td>3</td><td><code>ForceOvertimeModule</code></td><td>每帧</td><td><code>velocity</code></td><td>施加 3 轴曲线<strong>力场</strong>（加速度）</td><td>风、上冲、漩涡</td></tr><tr><td>4</td><td><code>VelocityOvertimeModule</code></td><td>每帧</td><td><code>ultimateVelocity</code></td><td><strong>直接注入速度</strong>，并整体缩放</td><td>喷射、上飘</td></tr><tr><td>5</td><td><code>LimitVelocityOvertimeModule</code></td><td>每帧</td><td><code>ultimateVelocity</code></td><td>超过阈值就衰减，即空气阻力</td><td>爆炸余波、减速</td></tr><tr><td>6</td><td><code>RotationOvertimeModule</code></td><td>每帧</td><td>旋转四元数</td><td>角速度式自转（逐帧累乘）</td><td>火星翻滚、落叶</td></tr><tr><td>7</td><td><code>TextureAnimationModule</code></td><td>每帧</td><td><code>frameIndex</code></td><td>序列帧翻页</td><td>爆炸动画、魔法阵</td></tr><tr><td>8</td><td><code>NoiseModule</code></td><td>每帧</td><td><code>position</code></td><td>噪声扰动位置（<strong>不碰速度</strong>）</td><td>烟、雾、飘动</td></tr><tr><td>—</td><td><code>ShapeModule</code></td><td><strong>出生</strong></td><td><code>position</code> + <code>velocity</code></td><td>决定从哪出生、朝哪个方向</td><td>Cone 火焰、Circle 法阵</td></tr><tr><td>—</td><td><code>TrailModule</code></td><td>每帧（独立）</td><td>独立的第二条 Model</td><td>粒子走过的路径拉成带子</td><td>流星、刀光</td></tr></tbody></table><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档&quot;">​</a></h2><ol><li><a href="https://docs.cocos.com/creator/3.8/manual/zh/particle-system/overview.html" target="_blank" rel="noreferrer">cocos 3D 粒子系统</a></li></ol>',14))])}const y=r(h,[["render",u]]);export{R as __pageData,y as default};
